package com.smartfile.config;
import com.smartfile.entity.*;import com.smartfile.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;import java.time.Instant;import java.time.temporal.ChronoUnit;import java.util.List;
@Configuration public class DemoSeed {@Bean CommandLineRunner seed(UserRepository users,DepartmentRepository departments,ApplicationRepository apps,WorkflowActionRepository actions,PasswordEncoder encoder){return args->{for(String n:List.of("Education","Revenue","Urban Development","Social Welfare","Public Works","Commerce","Finance","Legal"))if(departments.findByNameIgnoreCase(n).isEmpty())departments.save(new Department(n));String[][] accounts={{"citizen@smartfile.demo","CITIZEN","Rahul Sharma"},{"clerk@smartfile.demo","CLERK","Priya Nair"},{"officer@smartfile.demo","OFFICER","Arjun Kapoor"},{"admin@smartfile.demo","ADMIN","Aarav Mehta"}};for(var row:accounts)if(users.findByEmail(row[0]).isEmpty()){AppUser u=new AppUser();u.email=row[0];u.role=row[1];u.fullName=row[2];u.passwordHash=encoder.encode("SmartFile@2026");users.save(u);}if(apps.count()==0){String[] titles={"Scholarship application","Building permit renewal","Senior citizen pension","Business registration","Water connection request","Land record correction","Student travel concession","Birth certificate correction","Streetlight maintenance","Small business grant","Ration card update","Disability pension","Property tax appeal","School transfer certificate","Road repair request","Education stipend","Trade license renewal","Family income certificate","Drainage complaint","Widow pension"};String[] names={"Rahul Sharma","Ananya Iyer","Mohan Das","Aditi Verma","Farhan Ali","Meera Nair","Sana Khan","Vikram Rao","Kavita Joshi","Rohan Gupta"};String[] deps={"Education","Urban Development","Social Welfare","Commerce","Public Works","Revenue"};String[] statuses={"Officer review","Finance review","Document check","Approved","Returned","Submitted","Final approval"};for(int i=0;i<20;i++){SmartApplication a=new SmartApplication();a.fileId="SF-"+java.time.Year.now().getValue()+"-"+String.format("%04d",i+1);a.applicationType=titles[i];a.applicantName=i==0?"Rahul Sharma":names[i%names.length];a.department=departments.findByNameIgnoreCase(deps[i%deps.length]).orElseThrow();a.status=statuses[i%statuses.length];a.priority=i%5==0?"High":"Normal";a.submittedAt=Instant.now().minus(i+1,ChronoUnit.DAYS);a.deadline=Instant.now().minus(i%4==0?1:-1,ChronoUnit.DAYS);a.currentStage=a.status;apps.save(a);actions.save(new WorkflowAction(a,"system@smartfile.demo","SUBMITTED","Seeded demonstration application"));}}};}}
